#include <bits/stdc++.h>
using namespace std;

/*
 * Ideia: comprima a rua em blocos de alturas iguais v[1..m] (v[i] != v[i+1]).
 * Uma fase incrementa um bloco inteiro em 1; quando um bloco atinge a altura
 * do vizinho, eles se fundem. O processo de fusões forma uma árvore binária
 * sobre os blocos, onde cada nó interno corresponde a uma fusão ocorrida em
 * uma altura t >= max(v no intervalo do nó), e o total de fases é:
 *
 *      H + soma(t dos nós internos) - soma(h das folhas)
 *
 * com H = altura final >= max global (ótimo: H = max global), e cada t
 * aguenta no mínimo max do intervalo correspondente. Logo basta minimizar
 * a soma dos t's sobre todas as árvores binárias fundíveis:
 *
 *      W(l, r) = max(v[l..r]) + min_k ( W(l,k) + W(k+1,r) ),  W(l,l) = 0
 *
 * Resposta = max global + W(1,m) - soma de todos os v[i].
 * Verificado nos exemplos (2, 4, 0) e vários casos pequenos.
 */

int main(){
    int n;
    if(scanf("%d", &n) != 1) return 0;
    vector<int> a(n);
    for(int i = 0; i < n; ++i) scanf("%d", &a[i]);

    vector<int> v;
    v.reserve(n);
    for(int i = 0; i < n; ++i)
        if(v.empty() || v.back() != a[i]) v.push_back(a[i]);

    int m = (int)v.size();

    // MX[l][r] = max de v[l..r]
    vector<vector<int>> MX(m, vector<int>(m, 0));
    for(int l = 0; l < m; ++l){
        MX[l][l] = v[l];
        for(int r = l + 1; r < m; ++r)
            MX[l][r] = max(MX[l][r-1], v[r]);
    }

    // DP de intervalos
    vector<vector<int>> W(m, vector<int>(m, 0));
    for(int len = 2; len <= m; ++len){
        for(int l = 0; l + len - 1 < m; ++l){
            int r = l + len - 1;
            int best = INT_MAX;
            int* Wl = W[l].data();
            for(int k = l; k < r; ++k){
                int c = Wl[k] + W[k+1][r];
                if(c < best) best = c;
            }
            W[l][r] = MX[l][r] + best;
        }
    }

    long long sum = 0;
    for(int x : v) sum += x;
    long long ans = (long long)MX[0][m-1] + W[0][m-1] - sum;
    printf("%lld\n", ans);
    return 0;
}
